import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

export function edgeOffset(placement: string | null, distance: number) {
  switch (placement) {
    case "top":
      return { x: 0, y: distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: -distance };
  }
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import {
  AnimatePresence,
  motion,
  useIsPresent,
  useReducedMotion,
} from "motion/react";
import { type ComponentProps, forwardRef, type ReactNode } from "react";
import { duration, easeOut, springLayout, transitionFor } from "./motion";
import { cn } from "./utils";

export interface PresenceListProps<T>
  extends Omit<ComponentProps<"ul">, "children"> {
  items: readonly T[];
  getKey: (item: T) => string | number;
  children: (item: T) => ReactNode;
}

const PresenceListRow = forwardRef<
  HTMLLIElement,
  { children: ReactNode; reducedMotion: boolean }
>(function PresenceListRow({ children, reducedMotion }, ref) {
  const isPresent = useIsPresent();
  return (
    <motion.li
      ref={ref}
      data-slot="presence-list-item"
      inert={!isPresent}
      aria-hidden={!isPresent || undefined}
      layout={reducedMotion ? false : "position"}
      initial={reducedMotion ? false : { opacity: 0, y: 6, scale: 0.98 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={reducedMotion ? { opacity: 0 } : { opacity: 0, y: -6, scale: 0.98 }}
      transition={transitionFor(reducedMotion, {
        duration: duration.base,
        ease: easeOut,
        layout: springLayout,
      })}
    >
      {children}
    </motion.li>
  );
});

export function PresenceList<T>({
  items,
  getKey,
  children,
  className,
  ...props
}: PresenceListProps<T>) {
  const reducedMotion = useReducedMotion() === true;
  return (
    <ul
      {...props}
      data-slot="presence-list"
      className={cn("relative grid gap-2", className)}
    >
      <AnimatePresence initial={false} mode="popLayout">
        {items.map((item) => (
          <PresenceListRow key={getKey(item)} reducedMotion={reducedMotion}>
            {children(item)}
          </PresenceListRow>
        ))}
      </AnimatePresence>
    </ul>
  );
}
